text:
{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Meridian Health Partners, Inc."],
   "quote": "(1) **Northwind Labs, Inc.** (\"Northwind\"); and\n\n(2) **Meridian Health Partners, Inc.** (\"Meridian\")."
  },
  "counterparty": {
   "value": "Meridian Health Partners, Inc.",
   "quote": "(2) **Meridian Health Partners, Inc.** (\"Meridian\")."
  },
  "effective_date": {
   "value": "2026-07-02",
   "quote": "made and entered into as of July 2, 2026 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 48,
   "quote": "for an initial period of forty-eight (48) months commencing on the Effective Date"
  },
  "auto_renewal": {
   "value": true,
   "quote": "this Agreement shall renew automatically for successive renewal periods of one (1) year each."
  },
  "renewal_notice_days": {
   "value": 90,
   "quote": "at least ninety days before the end of the then-current term"
  },
  "governing_law": {
   "value": "Texas",
   "quote": "the laws of the State of Texas"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": 45,
   "quote": "Invoices are payable on Net 45 terms."
  },
  "contract_value": {
   "value": 96000,
   "quote": "The subscription fee payable by Northwind is $96,000 per year."
  },
  "termination_for_convenience": {
   "value": true,
   "quote": "Either Party may terminate this Agreement for convenience by giving the other Party thirty (30) days' prior written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Lena Fischer",
   "email": "lena.fischer@meridian.example",
   "title": "Chief Operating Officer",
   "party": "Meridian Health Partners, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "high",
   "message": "The agreement has no limitation of liability clause, so Northwind's exposure to damages is uncapped, and there is no exclusion of consequential damages.",
   "quote": "EXCEPT AS EXPRESSLY SET OUT IN THIS AGREEMENT, NEITHER PARTY MAKES ANY OTHER WARRANTY, WHETHER EXPRESS OR IMPLIED"
  },
  {
   "id": "no_confidentiality_or_data_protection",
   "severity": "high",
   "message": "There is no confidentiality, data protection or security clause, which is a significant gap for a health-sector analytics vendor that may process sensitive data.",
   "quote": "Meridian provides a software-as-a-service analytics platform"
  },
  {
   "id": "long_initial_term_with_evergreen",
   "severity": "medium",
   "message": "A 48-month initial term (about $384,000 in total fees) renews automatically each year unless notice is given 90 days before term end. The mutual 30-day termination for convenience right softens this, but Meridian can also terminate on short notice, which creates service continuity risk.",
   "quote": "this Agreement shall renew automatically for successive renewal periods of one (1) year each."
  },
  {
   "id": "no_sla_or_support_terms",
   "severity": "medium",
   "message": "There are no service levels, uptime commitments, support terms or refund remedies for the platform; only a generic performance warranty applies.",
   "quote": "Each Party warrants that it shall perform its obligations under this Agreement in a professional and workmanlike manner"
  },
  {
   "id": "weak_dispute_resolution",
   "severity": "low",
   "message": "Dispute resolution is vague: no forum, venue or arbitration is specified, and there is no IP or indemnification clause.",
   "quote": "either Party may pursue the remedies available to it."
  },
  {
   "id": "annual_prepayment",
   "severity": "low",
   "message": "Fees are invoiced annually in advance, and no refund of prepaid fees is provided on early termination for convenience.",
   "quote": "The subscription fee shall be invoiced annually in advance."
  },
  {
   "id": "assignment_to_successor",
   "severity": "low",
   "message": "Either party may assign without consent in a merger or asset sale, so Northwind could end up contracting with an unknown successor.",
   "quote": "either Party may assign this Agreement to a successor in a merger or in a sale of substantially all of its assets."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a SaaS subscription in which Northwind Labs, Inc. pays Meridian Health Partners, Inc. $96,000 per year for an initial 48-month term starting July 2, 2026, then renews yearly unless either party gives 90 days' notice. It has Net 45 payment and a mutual 30-day termination for convenience, and it is governed by Texas law. It lacks a liability cap, confidentiality, data protection and service-level terms."
}
